/* 冒泡排序：朴素版 / 交换标志版 / 末位交换版 / 鸡尾酒（双向）版 的实测对照
   编译：gcc -std=c99 -Wall -Wextra
   核心结论：① 交换次数恒等于逆序对数 INV  ② 朴素版比较次数恒为 n(n-1)/2
             ③ 乌龟元素让冒泡的代价翻倍，鸡尾酒排序解决它  ④ 冒泡比直接插入贵约 50% */
#include <stdio.h>

#define MAX 16

typedef struct { int key; int tag; } Rec;

static void printRec(const Rec *a, int n)
{
    int i;
    for (i = 0; i < n; i++) {
        printf("%d", a[i].key);
        if (a[i].tag > 0) printf("(%c)", 'a' + a[i].tag - 1);
        if (i + 1 < n) printf(" ");
    }
}

static void swapRec(Rec *a, Rec *b) { Rec t = *a; *a = *b; *b = t; }

static int invRec(const Rec *a, int n)
{
    int i, j, c = 0;
    for (i = 0; i < n - 1; i++)
        for (j = i + 1; j < n; j++)
            if (a[i].key > a[j].key) c++;
    return c;
}

static int sortedRec(const Rec *a, int n)
{
    int i;
    for (i = 0; i < n - 1; i++) if (a[i].key > a[i + 1].key) return 0;
    return 1;
}

/* 版本一：朴素冒泡 —— 固定跑 n-1 趟，不管有没有提前排好 */
static void bubbleNaive(Rec *a, int n, int *cmp, int *swp, int *passes)
{
    int i, j;
    *cmp = 0; *swp = 0;
    for (i = 0; i < n - 1; i++)
        for (j = 0; j < n - 1 - i; j++) {
            (*cmp)++;
            if (a[j].key > a[j + 1].key) { swapRec(&a[j], &a[j + 1]); (*swp)++; }
        }
    *passes = n - 1;
}

/* 版本二：带交换标志 —— 某趟一次交换都没有说明整体已有序 */
static void bubbleFlag(Rec *a, int n, int *cmp, int *swp, int *passes)
{
    int i, j, swapped;
    *cmp = 0; *swp = 0; *passes = 0;
    for (i = 0; i < n - 1; i++) {
        swapped = 0;
        for (j = 0; j < n - 1 - i; j++) {
            (*cmp)++;
            if (a[j].key > a[j + 1].key) { swapRec(&a[j], &a[j + 1]); (*swp)++; swapped = 1; }
        }
        *passes = i + 1;
        if (!swapped) break;
    }
}

/* 版本三：记录最后一次交换位置 —— last 之后必然已有序，下趟边界收缩到 last */
static void bubbleLast(Rec *a, int n, int *cmp, int *swp, int *passes)
{
    int bound = n - 1, j, last, p = 0;
    *cmp = 0; *swp = 0;
    while (bound > 0) {
        last = 0;
        p++;
        for (j = 0; j < bound; j++) {
            (*cmp)++;
            if (a[j].key > a[j + 1].key) { swapRec(&a[j], &a[j + 1]); (*swp)++; last = j; }
        }
        bound = last;
    }
    *passes = p;
}

/* 版本四：鸡尾酒排序（双向冒泡）—— 一趟正向推最大值、一趟反向推最小值，专治乌龟元素 */
static void cocktail(Rec *a, int n, int *cmp, int *swp, int *rounds)
{
    int lo = 0, hi = n - 1, j, swapped, r = 0;
    *cmp = 0; *swp = 0;
    while (lo < hi) {
        swapped = 0;
        r++;
        for (j = lo; j < hi; j++) {
            (*cmp)++;
            if (a[j].key > a[j + 1].key) { swapRec(&a[j], &a[j + 1]); (*swp)++; swapped = 1; }
        }
        hi--;
        if (!swapped) break;
        swapped = 0;
        for (j = hi; j > lo; j--) {                 /* ★ j > lo 且比较 a[j-1] 与 a[j]，否则越界 */
            (*cmp)++;
            if (a[j - 1].key > a[j].key) { swapRec(&a[j - 1], &a[j]); (*swp)++; swapped = 1; }
        }
        lo++;
        if (!swapped) break;                        /* ★ 反向趟之后也要判断 */
    }
    *rounds = r;
}

/* 直接插入排序（哨兵版，与 ds-ch08-05 完全同口径）：用来和冒泡做代价对比。
   ★ 用哨兵版而不是「j >= 0 判界」版，是因为只有哨兵版的比较次数才精确等于
     INV + (n-1)：哨兵 a[0] 让内层循环一定能停下，每趟恰好做 k_i 次「移动用的比较」
     加 1 次「让循环停下的比较」。判界版在「本趟元素比前面全都小」时是靠 j 减到 -1
     停下的，那一次没有发生关键字比较，于是总比较会比公式少「到达表头的趟数」次，
     两张卡的数字就对不上了。
   ★ 数据放在 a[1..n]，下标 0 留给哨兵，调用方要自己留出这一格。 */
static void insertSentinel(Rec *a, int n, int *cmp, int *mv)
{
    int i, j;
    *cmp = 0; *mv = 0;
    for (i = 2; i <= n; i++) {
        a[0] = a[i]; (*mv)++;                              /* 存哨兵 */
        for (j = i - 1; a[0].key < a[j].key; j--) {
            a[j + 1] = a[j]; (*mv)++; (*cmp)++;            /* 后移 + 一次比较 */
        }
        (*cmp)++;                                          /* 让内层停下的那一次比较 */
        a[j + 1] = a[0]; (*mv)++;                          /* 写回 */
    }
}

int main(void)
{
    Rec a[MAX], w[MAX];
    int n, i, inv, ic, im;
    /* 六组数据：正序 / 教材例 / 逆序 / 乌龟 / 兔子 / 早交换（末位版的用武之地） */
    int keys[6][9] = {
        { 1, 2, 3, 4, 5, 6, 7, 8, 9 },
        { 49, 38, 65, 97, 76, 13, 27, 49, 4 },
        { 9, 8, 7, 6, 5, 4, 3, 2, 1 },
        { 2, 3, 4, 5, 6, 7, 8, 9, 1 },
        { 9, 1, 2, 3, 4, 5, 6, 7, 8 },
        { 5, 1, 2, 3, 4, 6, 7, 8, 9 }
    };
    const char *names[6] = { "A 正序", "B 教材例", "C 逆序",
                             "D 乌龟(1在末尾)", "E 兔子(9在开头)", "F 早交换" };
    int naiveCmp[6], allSwapEqInv = 1, allSorted = 1, allSameNaive = 1;

    n = 9;

    printf("== ① 教材例 {49,38,65,97,76,13,27,49*,04} 逐趟冒泡（n=%d）==\n", n);
    {
        int pass, j, sp, c1 = 0, s1 = 0;
        for (i = 0; i < n; i++) { a[i].key = keys[1][i]; a[i].tag = (i == 0) ? 1 : (i == 7 ? 2 : 0); }
        inv = invRec(a, n);
        printf("  初始 INV=%d：", inv);
        printRec(a, n);
        printf("\n");
        for (pass = 0; pass < n - 1; pass++) {
            sp = 0;
            for (j = 0; j < n - 1 - pass; j++) {
                c1++;
                if (a[j].key > a[j + 1].key) { swapRec(&a[j], &a[j + 1]); s1++; sp++; }
            }
            printf("  第%d趟（比较到 j=%d）：", pass + 1, n - 2 - pass);
            printRec(a, n);
            printf("   本趟交换 %d 次\n", sp);
        }
        printf("  合计：比较 %d 次 == n(n-1)/2 = %d ？%d；交换 %d 次 == INV=%d ？%d；已升序=%d\n",
               c1, n * (n - 1) / 2, c1 == n * (n - 1) / 2, s1, inv, s1 == inv, sortedRec(a, n));
        printf("  ★ 两个 49 的次序：");
        printRec(a, n);
        printf(" → 49(a) 仍在 49(b) 前面？%d（第4趟 j=3 时两者相等、没有交换，稳定性就保住了）\n",
               a[4].tag == 1 && a[5].tag == 2);
    }

    printf("\n== ② 四个版本在 6 组数据上的实测（n=%d，交换次数应恒等于 INV）==\n", n);
    for (i = 0; i < 6; i++) {
        int k, cmpN, cmpF, cmpL, cmpC, pN, pF, pL, pC, sN, sF, sL, sC;
        for (k = 0; k < n; k++) { a[k].key = keys[i][k]; a[k].tag = 0; }
        inv = invRec(a, n);
        for (k = 0; k < n; k++) w[k] = a[k];
        bubbleNaive(w, n, &cmpN, &sN, &pN);
        if (!sortedRec(w, n)) allSorted = 0;
        if (sN != inv) allSwapEqInv = 0;
        naiveCmp[i] = cmpN;
        for (k = 0; k < n; k++) w[k] = a[k];
        bubbleFlag(w, n, &cmpF, &sF, &pF);
        if (!sortedRec(w, n)) allSorted = 0;
        if (sF != inv) allSwapEqInv = 0;
        for (k = 0; k < n; k++) w[k] = a[k];
        bubbleLast(w, n, &cmpL, &sL, &pL);
        if (!sortedRec(w, n)) allSorted = 0;
        if (sL != inv) allSwapEqInv = 0;
        for (k = 0; k < n; k++) w[k] = a[k];
        cocktail(w, n, &cmpC, &sC, &pC);
        if (!sortedRec(w, n)) allSorted = 0;
        if (sC != inv) allSwapEqInv = 0;
        printf("  %s INV=%d | 朴素 %d趟/%d比/%d换 | 标志 %d趟/%d比/%d换"
               " | 末位 %d趟/%d比/%d换 | 鸡尾酒 %d轮/%d比/%d换\n",
               names[i], inv, pN, cmpN, sN, pF, cmpF, sF, pL, cmpL, sL, pC, cmpC, sC);
    }
    for (i = 1; i < 6; i++) if (naiveCmp[i] != naiveCmp[0]) allSameNaive = 0;
    printf("  ★ 四版本 × 6 组数据共 24 次运行：交换次数全部等于 INV？%d，结果全部升序？%d\n",
           allSwapEqInv, allSorted);
    printf("  ★ 朴素版的比较次数在 6 组数据上全都相同？%d（都等于 n(n-1)/2 = %d，与数据完全无关）\n",
           allSameNaive, n * (n - 1) / 2);

    printf("\n== ③ 乌龟 vs 兔子：逆序对数相同、代价却差很多 ==\n");
    {
        int c1 = 0, s1 = 0, p1, c2 = 0, s2 = 0, p2;
        for (i = 0; i < n; i++) { a[i].key = keys[3][i]; a[i].tag = 0; }
        bubbleFlag(a, n, &c1, &s1, &p1);
        for (i = 0; i < n; i++) { a[i].key = keys[4][i]; a[i].tag = 0; }
        bubbleFlag(a, n, &c2, &s2, &p2);
        printf("  D 乌龟 [2..9,1]：标志版 %d 趟、比较 %d 次、交换 %d 次\n", p1, c1, s1);
        printf("  E 兔子 [9,1..8]：标志版 %d 趟、比较 %d 次、交换 %d 次\n", p2, c2, s2);
        printf("  ★ 交换次数相同（都等于 INV）？%d，但比较次数相差 %.2f 倍 → 代价不只看「有多乱」还看「乱在哪一头」\n",
               s1 == s2, (double)c1 / c2);
        for (i = 0; i < n; i++) { a[i].key = keys[3][i]; a[i].tag = 0; }
        cocktail(a, n, &c2, &s2, &p2);
        printf("  D 乌龟改用鸡尾酒：%d 轮、比较 %d 次、交换 %d 次 → 比单向冒泡省 %.1f%%\n",
               p2, c2, s2, 100.0 * (double)(c1 - c2) / c1);
    }

    printf("\n== ④ 与直接插入排序的代价对比（同一组数据）==\n");
    for (i = 1; i <= 2; i++) {
        int bc = 0, bs = 0, bp;
        int k;
        for (k = 0; k < n; k++) { a[k].key = keys[i][k]; a[k].tag = 0; }
        inv = invRec(a, n);
        bubbleFlag(a, n, &bc, &bs, &bp);
        for (k = 1; k <= n; k++) { a[k].key = keys[i][k - 1]; a[k].tag = 0; }   /* 下标 0 留给哨兵 */
        insertSentinel(a, n, &ic, &im);
        printf("  %s INV=%d：冒泡 比较%d 交换%d（移动 %d 次赋值）合计%d | 直接插入 比较%d 移动%d 合计%d\n",
               names[i], inv, bc, bs, 3 * bs, bc + 3 * bs, ic, im, ic + im);
        printf("            直接插入的两个精确等式：比较 %d == INV+(n-1) = %d ?%d，移动 %d == INV+2(n-1) = %d ?%d\n",
               ic, inv + n - 1, ic == inv + n - 1, im, inv + 2 * (n - 1), im == inv + 2 * (n - 1));
        printf("            → 冒泡比直接插入贵 %.1f%%；移动次数是它的 %.2f 倍（3·INV=%d vs INV+2(n-1)=%d）\n",
               100.0 * (double)(bc + 3 * bs - ic - im) / (ic + im), (double)(3 * bs) / im,
               3 * inv, inv + 2 * (n - 1));
    }

    return 0;
}

/* 快速排序：填坑法划分、三种枢轴策略、三路划分、不稳定反例
   编译：gcc -std=c99 -Wall -Wextra
   核心结论：① 教材例第一趟划分结果与严蔚敏教材完全一致
             ② 有序输入 + 端点枢轴 = 最坏 O(n^2)，三数取中把它救回来
             ③ 全相同元素上三路划分只做 1 次划分，普通快排要做 n-1 次
             ④ 快排不稳定，3 个元素就能造出反例 */
#include <stdio.h>

#define MAX 32

typedef struct { int key; int tag; } Rec;

static void printRec(const Rec *a, int n)
{
    int i;
    for (i = 0; i < n; i++) {
        printf("%d", a[i].key);
        if (a[i].tag > 0) printf("(%c)", 'a' + a[i].tag - 1);
        if (i + 1 < n) printf(" ");
    }
}

static void swapRec(Rec *a, Rec *b) { Rec t = *a; *a = *b; *b = t; }

static int sortedRec(const Rec *a, int n)
{
    int i;
    for (i = 0; i < n - 1; i++) if (a[i].key > a[i + 1].key) return 0;
    return 1;
}

/* 填坑法划分。cmp 统计关键字比较次数（每次判断算一次） */
static int partition(Rec *a, int low, int high, int *cmp)
{
    Rec pv = a[low];
    while (low < high) {
        while (low < high) { (*cmp)++; if (a[high].key >= pv.key) high--; else break; }
        a[low] = a[high];
        while (low < high) { (*cmp)++; if (a[low].key <= pv.key) low++; else break; }
        a[high] = a[low];
    }
    a[low] = pv;
    return low;
}

/* 三数取中：3 次比较把 a[low]、a[mid]、a[high] 排好，再把中位数换到 low 当枢轴 */
static void median3(Rec *a, int low, int high, int *cmp)
{
    int mid = low + (high - low) / 2;
    (*cmp)++; if (a[low].key > a[mid].key) swapRec(&a[low], &a[mid]);
    (*cmp)++; if (a[low].key > a[high].key) swapRec(&a[low], &a[high]);
    (*cmp)++; if (a[mid].key > a[high].key) swapRec(&a[mid], &a[high]);
    swapRec(&a[low], &a[mid]);
}

/* 确定性伪随机（LCG），保证输出可复现 */
static unsigned long long rngState = 20260101ULL;
static int nextRand(int bound)
{
    rngState = rngState * 6364136223846793005ULL + 1442695040888963407ULL;
    return (int)((rngState >> 33) % (unsigned)bound);
}

/* strategy: 0=端点枢轴 1=随机枢轴 2=三数取中。verbose 为真时打印每次划分后的整个序列 */
static void quickSort(Rec *a, int low, int high, int n, int strategy, int verbose,
                      int *cmp, int *parts, int *maxDepth, int depth)
{
    int p;
    if (low >= high) return;
    if (depth > *maxDepth) *maxDepth = depth;
    if (strategy == 1) swapRec(&a[low], &a[low + nextRand(high - low + 1)]);
    else if (strategy == 2) median3(a, low, high, cmp);
    p = partition(a, low, high, cmp);
    (*parts)++;
    if (verbose) {
        printf("    划分 [%d..%d]（深度%d）→ 枢轴 %d 落位到下标 %d：", low, high, depth, a[p].key, p);
        printRec(a, n);
        printf("\n");
    }
    quickSort(a, low, p - 1, n, strategy, verbose, cmp, parts, maxDepth, depth + 1);
    quickSort(a, p + 1, high, n, strategy, verbose, cmp, parts, maxDepth, depth + 1);
}

/* 三路划分（Dutch national flag）：< pv | == pv | > pv，中间那段不再递归 */
static void quickSort3(Rec *a, int low, int high, int *cmp, int *parts, int *maxDepth, int depth)
{
    int lt, gt, i;
    Rec pv;
    if (low >= high) return;
    if (depth > *maxDepth) *maxDepth = depth;
    pv = a[low];
    lt = low; gt = high; i = low + 1;
    while (i <= gt) {
        (*cmp)++;
        if (a[i].key < pv.key) { swapRec(&a[i], &a[lt]); lt++; i++; }
        else {
            (*cmp)++;
            if (a[i].key > pv.key) { swapRec(&a[i], &a[gt]); gt--; }   /* ★ i 不动 */
            else i++;
        }
    }
    (*parts)++;
    quickSort3(a, low, lt - 1, cmp, parts, maxDepth, depth + 1);
    quickSort3(a, gt + 1, high, cmp, parts, maxDepth, depth + 1);
}

