#include <stdio.h>

#define MAX 128
#define MAXTOUR 256

typedef struct { int key; int tag; } Rec;

static unsigned long long rngState = 20260101ULL;

static int nextRand(int bound)
{
    rngState = rngState * 6364136223846793005ULL + 1442695040888963407ULL;
    return (int)((rngState >> 33) % (unsigned long long)bound);
}

static void printRec(const Rec *a, int n)
{
    int i;
    for (i = 0; i < n; i++) {
        if (i > 0) printf(" ");
        if (a[i].tag > 0) printf("%d(%c)", a[i].key, 'a' + a[i].tag - 1);
        else printf("%d", a[i].key);
    }
    printf("\n");
}

static int sortedRec(const Rec *a, int n)
{
    int i;
    for (i = 1; i < n; i++) if (a[i - 1].key > a[i].key) return 0;
    return 1;
}

static int sortedInt(const int *v, int n)
{
    int i;
    for (i = 1; i < n; i++) if (v[i - 1] > v[i]) return 0;
    return 1;
}

static int invRec(const Rec *a, int n)
{
    int i, j, c = 0;
    for (i = 0; i < n; i++)
        for (j = i + 1; j < n; j++)
            if (a[i].key > a[j].key) c++;
    return c;
}

static int ceilLog2(int n)
{
    int c = 0, t;
    for (t = 1; t < n; t *= 2) c++;
    return c;
}

/* ---------- 简单选择排序 ---------- */
static void selectSort(Rec *a, int n, int *cmp, int *swp, int verbose)
{
    int i, j, min;
    *cmp = 0; *swp = 0;
    for (i = 0; i < n - 1; i++) {
        min = i;
        for (j = i + 1; j < n; j++) {
            (*cmp)++;
            if (a[j].key < a[min].key) min = j;      /* 严格小于：相等时保留靠前的 */
        }
        if (verbose)
            printf("   第%d趟：a[%d..%d] 里最小值是 %d（在下标 %d）%s\n",
                   i + 1, i, n - 1, a[min].key, min,
                   min == i ? "，它本来就在位，不交换" : "，与 a[i] 交换");
        if (min != i) {
            Rec t = a[i]; a[i] = a[min]; a[min] = t;
            (*swp)++;
        }
        if (verbose) { printf("            -> "); printRec(a, n); }
    }
}

/* ---------- 冒泡（标志版）与直接插入（哨兵版）：用于三方对比 ---------- */
static void bubbleFlag(Rec *a, int n, int *cmp, int *swp)
{
    int i, j, swapped;
    *cmp = 0; *swp = 0;
    for (i = n - 1; i > 0; i--) {
        swapped = 0;
        for (j = 0; j < i; j++) {
            (*cmp)++;
            if (a[j].key > a[j + 1].key) {
                Rec t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;
                (*swp)++; swapped = 1;
            }
        }
        if (!swapped) break;
    }
}

/* 直接插入排序（哨兵版）：与 ds-ch08-05 口径一致，
   比较次数严格等于 INV + (n-1)、移动次数严格等于 INV + 2(n-1) */
static void insertSentinel(Rec *a, int n, int *cmp, int *mv)
{
    int i, j;
    *cmp = 0; *mv = 0;
    for (i = 2; i <= n; i++) {
        a[0] = a[i]; (*mv)++;
        for (j = i - 1; a[0].key < a[j].key; j--) { a[j + 1] = a[j]; (*mv)++; (*cmp)++; }
        (*cmp)++;
        a[j + 1] = a[0]; (*mv)++;
    }
}

/* ---------- 树形选择排序（锦标赛排序） ----------
   tree[0..2n-2] 存的是「胜者的下标」，-1 表示已淘汰。
   叶子在 tree[n-1 .. 2n-2]，内部结点在 tree[0 .. n-2]；
   结点 i 的孩子是 2i+1 与 2i+2，父结点是 (i-1)/2。
   ★ 必须存下标而不是存值：有重复关键字时，存值就分不清是哪个叶子赢了。 */
static int winner(const Rec *a, int x, int y, int *cmp)
{
    if (x < 0) return y;
    if (y < 0) return x;
    (*cmp)++;                                 /* 只有两边都有效才算一次关键字比较 */
    return (a[x].key <= a[y].key) ? x : y;    /* 平局取下标小的（靠左的叶子） */
}

static void printTour(const Rec *a, const int *tree, int n)
{
    int size = 2 * n - 1, lvl = 1, i = 0;
    while (i < size) {
        int j, end = i + lvl;
        if (end > size) end = size;
        printf("        ");
        for (j = i; j < end; j++) {
            if (tree[j] < 0) printf("[--]");
            else printf("[%2d]", a[tree[j]].key);
        }
        printf("\n");
        i = end;
        lvl *= 2;
    }
}

/* 返回总比较次数；*buildCmp 是建树那一步用掉的 */
static int tourSort(const Rec *a, int n, int *out, int *buildCmp, int verbose)
{
    int tree[MAXTOUR];
    int i, k, pos, cmp = 0;
    if (n <= 0) { *buildCmp = 0; return 0; }
    if (n == 1) { out[0] = a[0].key; *buildCmp = 0; return 0; }
    for (i = 0; i < n; i++) tree[n - 1 + i] = i;
    for (i = n - 2; i >= 0; i--)
        tree[i] = winner(a, tree[2 * i + 1], tree[2 * i + 2], &cmp);
    *buildCmp = cmp;
    if (verbose) {
        printf("      建好的锦标赛树（第1行是根=全局最小，最后一行是 n 个叶子）：\n");
        printTour(a, tree, n);
    }
    for (k = 0; k < n; k++) {
        out[k] = a[tree[0]].key;
        pos = 0;
        while (pos < n - 1)                              /* 沿胜者路径走到叶子 */
            pos = (tree[2 * pos + 1] == tree[pos]) ? 2 * pos + 1 : 2 * pos + 2;
        if (verbose && k < 2)
            printf("      输出第%d小 = %d（来自叶子 tree[%d]），淘汰它并沿路径重新比较：\n",
                   k + 1, out[k], pos);
        tree[pos] = -1;
        for (pos = (pos - 1) / 2; ; pos = (pos - 1) / 2) {
            tree[pos] = winner(a, tree[2 * pos + 1], tree[2 * pos + 2], &cmp);
            if (pos == 0) break;
        }
        if (verbose && k < 2) printTour(a, tree, n);
    }
    return cmp;
}

