#include <stdio.h>

#define MAX 256

typedef struct { int key; int tag; } Rec;

static unsigned long long rngState = 20260101ULL;

static int nextRand(int bound)
{
    rngState = rngState * 6364136223846793005ULL + 1442695040888963407ULL;
    return (int)((rngState >> 33) % (unsigned long long)bound);
}

static void printRec(const Rec *a, int n)
{
    int i;
    for (i = 0; i < n; i++) {
        if (i > 0) printf(" ");
        if (a[i].tag > 0) printf("%d(%c)", a[i].key, 'a' + a[i].tag - 1);
        else printf("%d", a[i].key);
    }
    printf("\n");
}

static int sortedRec(const Rec *a, int n)
{
    int i;
    for (i = 1; i < n; i++) if (a[i - 1].key > a[i].key) return 0;
    return 1;
}

static int isMaxHeap(const Rec *a, int n)
{
    int i;
    for (i = 0; i < n / 2; i++) {
        if (2 * i + 1 < n && a[i].key < a[2 * i + 1].key) return 0;
        if (2 * i + 2 < n && a[i].key < a[2 * i + 2].key) return 0;
    }
    return 1;
}

static int ceilLog2(int n)
{
    int c = 0, t;
    for (t = 1; t < n; t *= 2) c++;
    return c;
}

/* 大根堆下调：在 a[0..size-1] 里把 a[i] 沉到合适位置。
   cmp 数关键字比较次数，steps 数实际下沉（交换）的层数。 */
static void siftDown(Rec *a, int i, int size, int *cmp, int *steps)
{
    int child = 2 * i + 1;
    while (child < size) {
        if (child + 1 < size) {
            (*cmp)++;
            if (a[child + 1].key > a[child].key) child++;    /* 选较大的孩子 */
        }
        (*cmp)++;
        if (a[i].key >= a[child].key) break;                 /* 已满足堆性质 */
        { Rec t = a[i]; a[i] = a[child]; a[child] = t; }
        (*steps)++;
        i = child;
        child = 2 * i + 1;
    }
}

/* 建堆：必须从最后一个非叶结点 n/2-1 倒着往前，
   因为 siftDown 的前提是「以两个孩子为根的子树已经是堆」。 */
static void buildHeap(Rec *a, int n, int *cmp, int *steps, int verbose)
{
    int i;
    for (i = n / 2 - 1; i >= 0; i--) {
        int before = *steps;
        siftDown(a, i, n, cmp, steps);
        if (verbose) {
            printf("   siftDown(下标 %d)：下沉 %d 层 -> ", i, *steps - before);
            printRec(a, n);
        }
    }
}

/* 逐个插入 + 上浮建堆：这是 O(n log n) 的那种建堆法，用来和 siftDown 建堆对比 */
static void siftUp(Rec *a, int i, int *cmp, int *steps)
{
    while (i > 0) {
        int p = (i - 1) / 2;
        (*cmp)++;
        if (a[p].key >= a[i].key) break;
        { Rec t = a[p]; a[p] = a[i]; a[i] = t; }
        (*steps)++;
        i = p;
    }
}

static void buildByInsert(Rec *a, int n, int *cmp, int *steps)
{
    int i;
    for (i = 1; i < n; i++) siftUp(a, i, cmp, steps);
}

int main(void)
{
    Rec a[MAX], b[MAX];
    int src[9], sizes[5];
    int i, k, n;

    src[0] = 49; src[1] = 38; src[2] = 65; src[3] = 97; src[4] = 76;
    src[5] = 13; src[6] = 27; src[7] = 49; src[8] = 4;
    n = 9;

    printf("== ①② 建堆与排序全过程（教材例 n=9，两个 49 用 (a)(b) 标记）==\n");
    {
        int cmp = 0, steps = 0, bCmp, bSteps, size, pass = 0;
        for (k = 0; k < n; k++) {
            a[k].key = src[k];
            a[k].tag = (k == 0) ? 1 : ((k == 7) ? 2 : 0);
        }
        printf("   初始（按完全二叉树的层序摆放）："); printRec(a, n);
        printf("   最后一个非叶结点下标 = n/2-1 = %d，从它开始倒着逐个 siftDown\n", n / 2 - 1);
        buildHeap(a, n, &cmp, &steps, 1);
        bCmp = cmp; bSteps = steps;
        printf("   建堆完成："); printRec(a, n);
        printf("   是大根堆？%d；建堆用了比较 %d 次、下沉 %d 层；★ %d < 2n = %d ？%d\n",
               isMaxHeap(a, n), bCmp, bSteps, bCmp, 2 * n, bCmp < 2 * n);
        {
            int q1 = -1, q2 = -1;
            for (k = 0; k < n; k++) { if (a[k].tag == 1) q1 = k; if (a[k].tag == 2) q2 = k; }
            printf("   ★ 建堆后 49(a) 在下标 %d、49(b) 在下标 %d（初始分别是 0 和 7）-> 建堆阶段两者就已颠倒？%d\n",
                   q1, q2, q2 < q1);
        }
        for (size = n - 1; size > 0; size--) {
            Rec t = a[0]; a[0] = a[size]; a[size] = t;
            pass++;
            printf("   第%d趟：堆顶 %d 换到 a[%d]，堆长度减为 %d -> ", pass, a[size].key, size, size);
            printRec(a, n);
            siftDown(a, 0, size, &cmp, &steps);
        }
        printf("   排序完成："); printRec(a, n);
        printf("   已升序？%d；建堆 比较%d/下沉%d，排序阶段 比较%d/下沉%d，合计比较 %d\n",
               sortedRec(a, n), bCmp, bSteps, cmp - bCmp, steps - bSteps, cmp);
        printf("   ★ 两个 49 的最终次序：");
        {
            int p1 = -1, p2 = -1;
            for (k = 0; k < n; k++) { if (a[k].tag == 1) p1 = k; if (a[k].tag == 2) p2 = k; }
            printf("49(a) 在下标 %d、49(b) 在下标 %d -> 49(a) 仍在前面？%d\n", p1, p2, p1 < p2);
            printf("     （建堆时颠倒、排序时又换回来，所以这个例子仍不能证明稳定性；见 ⑤ 的最小反例）\n");
        }
    }

    printf("\n== ③ 建堆是 O(n) 的实证：比较次数与 n 成正比，而不是与 n·log n 成正比 ==\n");
    {
        double perN[5], perNL[5];
        int lgs[5];
        sizes[0] = 8; sizes[1] = 16; sizes[2] = 32; sizes[3] = 64; sizes[4] = 128;
        for (i = 0; i < 5; i++) {
            int m = sizes[i], cmp = 0, steps = 0, lg = ceilLog2(m);
            rngState = 20260101ULL;
            for (k = 0; k < m; k++) { a[k].key = nextRand(10000); a[k].tag = 0; }
            buildHeap(a, m, &cmp, &steps, 0);
            lgs[i] = lg;
            perN[i] = (double)cmp / m;
            perNL[i] = (double)cmp / ((double)m * lg);
            printf("   n=%d：建堆比较 %d 次、下沉 %d 层；是大根堆？%d\n", m, cmp, steps, isMaxHeap(a, m));
            printf("        比较/n = %.3f，比较/(n·ceil(log2 n)) = %.4f\n", perN[i], perNL[i]);
        }
        printf("   ★ 判据一：n 从 %d 到 %d，ceil(log2 n) 从 %d 涨到 %d（×%.2f）。\n",
               sizes[0], sizes[4], lgs[0], lgs[4], (double)lgs[4] / (double)lgs[0]);
        printf("     若建堆是 Θ(n log n)，「比较/n」也该涨同样倍数；实测它只从 %.3f 涨到 %.3f（×%.2f），远小于 %.2f\n",
               perN[0], perN[4], perN[4] / perN[0], (double)lgs[4] / (double)lgs[0]);
        printf("   ★ 判据二：「比较/(n·log n)」从 %.4f 单调降到 %.4f —— 若真是 Θ(n log n)，这个比值应该是常数\n",
               perNL[0], perNL[4]);
        printf("     两条合起来 ⇒ 建堆的比较次数与 n 成正比，是 O(n) 而不是 O(n log n)\n");
    }

    printf("\n== ④ 两种建堆法对比：siftDown 建堆 vs 逐个插入 siftUp 建堆（n=64）==\n");
    {
        int m = 64, d, sdCmp[2], suCmp[2];
        for (d = 0; d < 2; d++) {
            int c1 = 0, s1 = 0, c2 = 0, s2 = 0;
            rngState = 20260101ULL;
            for (k = 0; k < m; k++) {
                a[k].key = (d == 0) ? nextRand(10000) : k + 1;   /* 0=伪随机；1=升序（siftUp 的最坏情况） */
                a[k].tag = 0;
                b[k] = a[k];
            }
            buildHeap(a, m, &c1, &s1, 0);
            buildByInsert(b, m, &c2, &s2);
            sdCmp[d] = c1; suCmp[d] = c2;
            printf("   %s：siftDown 建堆 比较%d 下沉%d 是堆？%d | siftUp 建堆 比较%d 上浮%d 是堆？%d | siftUp/siftDown = %.2f 倍\n",
                   d == 0 ? "伪随机数据" : "升序数据(siftUp 的最坏情况)",
                   c1, s1, isMaxHeap(a, m), c2, s2, isMaxHeap(b, m), (double)c2 / (double)c1);
            printf("        两者堆顶相同？%d（堆顶一定是全局最大值，与建堆方法无关）\n", a[0].key == b[0].key);
        }
        printf("   ★ siftDown 建堆：伪随机 %d 次、升序 %d 次 —— 同一个量级。\n", sdCmp[0], sdCmp[1]);
        printf("     它的界 Σ⌈n/2^(h+1)⌉·h 只取决于结点的**高度**，与关键字取值无关，所以对任何输入都是 O(n)\n");
        printf("   ★ siftUp 建堆：伪随机 %d 次、升序 %d 次 —— 升序时暴涨 %.2f 倍\n",
               suCmp[0], suCmp[1], (double)suCmp[1] / (double)suCmp[0]);
        printf("     成因：升序时每个新元素都是当前最大值，要一路上浮到根，Σ ceil(log2 i) = Θ(n log n)\n");
        printf("     ⇒「siftUp 建堆差一个 log n 因子」是**最坏情况**结论；随机数据下 siftUp 的期望也是 O(n)\n");
        printf("       （每上浮一层的概率只有 1/2，期望只上浮 2 层），所以伪随机这一组两者只差 %.2f 倍\n",
               (double)suCmp[0] / (double)sdCmp[0]);
    }

    printf("\n== ⑤ 不稳定的最小反例：3 个元素 ==\n");
    {
        int m = 3, cmp = 0, steps = 0, size, p1 = -1, p2 = -1;
        int ks[3], tg[3];
        ks[0] = 3; ks[1] = 5; ks[2] = 5;
        tg[0] = 0; tg[1] = 1; tg[2] = 2;
        for (k = 0; k < m; k++) { a[k].key = ks[k]; a[k].tag = tg[k]; }
        printf("   初始："); printRec(a, m);
        buildHeap(a, m, &cmp, &steps, 0);
        printf("   建堆后："); printRec(a, m);
        {
            int q1 = -1, q2 = -1;
            for (k = 0; k < m; k++) { if (a[k].tag == 1) q1 = k; if (a[k].tag == 2) q2 = k; }
            printf("   ★ 建堆后 5(a) 在下标 %d、5(b) 在下标 %d -> 建堆阶段两者的相对次序就颠倒了？%d\n",
                   q1, q2, q2 < q1);
        }
        for (size = m - 1; size > 0; size--) {
            Rec t = a[0]; a[0] = a[size]; a[size] = t;
            printf("   第%d趟：堆顶 %d 换到 a[%d]，堆长度减为 %d -> ", m - size, a[size].key, size, size);
            printRec(a, m);
            siftDown(a, 0, size, &cmp, &steps);
        }
        printf("   排序后："); printRec(a, m);
        for (k = 0; k < m; k++) { if (a[k].tag == 1) p1 = k; if (a[k].tag == 2) p2 = k; }
        printf("   ★ 5(b) 排到了 5(a) 前面？%d -> 不稳定（已升序？%d）\n", p2 < p1, sortedRec(a, m));
        printf("     成因：建堆时 5(a) 上浮到根，排序第一趟又把根与末尾的 5(b) 交换，两个相等元素就此颠倒\n");
    }
