## 算法：分治的三步

```c
void MergeSort(RecType a[], int low, int high, RecType tmp[])
{
    int mid;
    if (low >= high) return;              /* ★ 必须是 >=，不能是 == */
    mid = low + (high - low) / 2;         /* ★ 防溢出，不能写 (low+high)/2 */
    MergeSort(a, low, mid, tmp);
    MergeSort(a, mid + 1, high, tmp);
    Merge(a, low, mid, high, tmp);
}

void Merge(RecType a[], int low, int mid, int high, RecType tmp[], int stable)
{
    int i = low, j = mid + 1, k = low;
    while (i <= mid && j <= high)
        if (stable ? (a[i].key <= a[j].key) : (a[i].key < a[j].key))
            tmp[k++] = a[i++];            /* ★ 相等时取左边 —— 稳定性全在这一行 */
        else
            tmp[k++] = a[j++];
    while (i <= mid)  tmp[k++] = a[i++];
    while (j <= high) tmp[k++] = a[j++];
    for (k = low; k <= high; k++) a[k] = tmp[k];   /* 拷回，别忘了 */
}
```

## ★★ 稳定性就在 `<=` 那一个字符上

合并两个有序段时，如果 `a[i].key == a[j].key`（i 在左半段、j 在右半段，所以 a[i] 原本在 a[j] **前面**）：

- 写 `<=` → 条件为真 → 取 a[i] → **前面的先出来，稳定性保住**
- 写 `<` → 条件为假 → 取 a[j] → **后面的先出来，两个相等元素颠倒，不稳定**

这是排序章节里最经典的「一个字符决定一个性质」的例子，与折半插入排序的 `a[0] >= a[mid]`（ds-ch08-06）、直接插入的 `a[0] < a[j]`（ds-ch08-05）是同一类考点。

## ★ 时间复杂度：最好 = 最坏 = 平均，比较次数几乎与数据无关

| 指标 | 值 | 与初始序列有关吗 |
|---|---|---|
| 关键字比较 | n=16 实测四组数据 **32 ~ 48** 次 | 有关，但**变化极小**（1.50 倍） |
| 元素移动 | 恒为 **2·n·log₂n** 次赋值（n=16 实测 128） | **完全无关** |
| 递归深度 | ⌈log₂n⌉ | 无关 |
| 时间复杂度 | **Θ(n log n)，最好=最坏=平均** | 无关 |

移动次数为什么与数据无关：每一层递归要把全部 n 个元素拷进 tmp 一次、再拷回 a 一次，共 2n 次赋值；一共 ⌈log₂n⌉ 层 ⇒ **2n·log₂n**。这与直接插入（INV+2(n−1)）、冒泡（3·INV）、快排（随划分平衡度剧变）都不同。

比较次数的上下界：n=2ᵏ 时，最好情况（正序或逆序，两个半段的值域完全分离）每层只需 n/2 次比较，共 **(n/2)·log₂n**；最坏情况（两段完全交错）每次合并用满 `len₁+len₂−1` 次，共 **n·log₂n − n + 1**。n=16 时就是 32 与 49。

★ **对照快排**：同样四组 n=16 的数据，端点枢轴快排的比较次数从 66 到 128 不等（正序 120、逆序 128 都是最坏量级，随机数据只有 66~75），而归并始终在 32~48 之间。**「最坏情况有保证」是归并相对快排最实在的优势 —— 而且归并的最大值 48 还小于快排的最小值 66。**

## ★ 空间 O(n)：它最主要的劣势

合并需要与原数组等长的辅助数组 `tmp[]`，加上递归栈 ⌈log₂n⌉ 层 ⇒ 空间 **O(n) + O(log n) = O(n)**。快排只要 O(log n) 栈空间、堆排只要 O(1)。

工程上的两个优化：

1. **辅助数组只分配一次**，从最外层传下去，而不是在每层递归里 `malloc`/`free`。n=100 万时递归有 20 层、约 2n 个结点，频繁分配的开销可能超过排序本身。
2. **自底向上（迭代）版本**彻底不要递归：按段长 1→2→4→8 逐层合并，栈空间降到 **O(1)**。

```c
void MergeSortBU(RecType a[], int n, RecType tmp[])
{
    int len, low, mid, high;
    for (len = 1; len < n; len *= 2)
        for (low = 0; low < n; low += 2 * len) {
            mid = low + len - 1;
            if (mid >= n - 1) break;         /* ★ 后半段为空，跳过，否则会越界读 */
            high = low + 2 * len - 1;
            if (high > n - 1) high = n - 1;
            Merge(a, low, mid, high, tmp, 1);
        }
}
```

★ n 是 2 的幂时，自底向上与自顶向下做的合并**完全一样**（只是顺序不同），比较次数与移动次数一字不差；n 不是 2 的幂时两者会有细微差别。

## ★ 为什么它是「唯一稳定且最坏 O(n log n)」的排序，以及这带来什么

| | 归并 | 快排 | 堆排 |
|---|---|---|---|
| 最坏时间 | **O(n log n)** | O(n²) | O(n log n) |
| 稳定 | **是** | 否 | 否 |
| 空间 | O(n) | O(log n) | **O(1)** |
| 缓存友好 | 一般（两个数组间跳） | **好**（顺序扫描） | 差（跳跃访问） |
| 实践速度 | 中（常数因子大） | **最快** | 慢（约为快排 2~3 倍） |

⇒ 三条推论：

- **需要稳定排序时只能用归并**（或计数/基数排序）。这就是 Java `Arrays.sort(Object[])` 用 TimSort（归并的改进）、Python `sorted()` 用 Timsort、C++ 的 `std::stable_sort` 用归并的原因；而它们的**非稳定**版本（`Arrays.sort(int[])`、`std::sort`）都用快排的变体。
- **链表上的归并排序能做到 O(1) 额外空间**：不需要辅助数组，合并时直接改指针即可；找中点用快慢指针。这是数组版本做不到的，也是「链表最适合的排序算法」。
- **外部排序只能用归并**：数据放不进内存时，快排与堆排都要随机访问整个序列，而归并只需要顺序读若干个子文件（多路平衡归并，见 8.7）。

## ★ 一个重要副产品：O(n log n) 数逆序对

合并时如果取了右边的元素 a[j]，说明**左半段剩下的 a[i..mid] 全都比 a[j] 大**，一次就能数出 `mid − i + 1` 个逆序对：

```c
if (a[i].key <= a[j].key) tmp[k++] = a[i++];
else { tmp[k++] = a[j++]; cnt += mid - i + 1; }   /* ★ 不是 cnt += 1 */
```

把暴力法的 O(n²) 降到 O(n log n)。这是归并排序在笔试与面试里最常见的应用。

examples.code:
#include <stdio.h>
#include <stdlib.h>

#define MAX 64

typedef struct { int key; int tag; } Rec;

/* 只输出数据体：不留尾随空格、不换行，label 由调用方一次 printf 打完整 */
static void printTagBody(const Rec *a, int n)
{
    int i;
    for (i = 0; i < n; i++) {
        if (i > 0) printf(" ");
        if (a[i].tag == 1) printf("%d(a)", a[i].key);
        else if (a[i].tag == 2) printf("%d(b)", a[i].key);
        else printf("%d", a[i].key);
    }
}

static int sortedRec(const Rec *a, int n)
{
    int i;
    for (i = 1; i < n; i++) if (a[i - 1].key > a[i].key) return 0;
    return 1;
}

static int invRec(const Rec *a, int n)     /* 暴力数逆序对，O(n^2)，用来验证归并法 */
{
    int i, j, c = 0;
    for (i = 0; i < n; i++) for (j = i + 1; j < n; j++) if (a[i].key > a[j].key) c++;
    return c;
}

static unsigned long long rngState = 20260101ULL;
static int nextRand(int bound)
{
    rngState = rngState * 6364136223846793005ULL + 1442695040888963407ULL;
    return (int)((rngState >> 33) % (unsigned)bound);
}

/* 合并。★ 稳定性就在 stable ? <= : < 这一个字符上 */
static void mergeRec(Rec *a, int low, int mid, int high, Rec *tmp,
                     int *cmp, int *mv, int stable)
{
    int i = low, j = mid + 1, k = low;
    while (i <= mid && j <= high) {
        (*cmp)++;
        if (stable ? (a[i].key <= a[j].key) : (a[i].key < a[j].key)) tmp[k++] = a[i++];
        else tmp[k++] = a[j++];
    }
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= high) tmp[k++] = a[j++];
    for (k = low; k <= high; k++) a[k] = tmp[k];
    (*mv) += 2 * (high - low + 1);      /* 拷进 tmp 一次、拷回 a 一次 */
}

static void mergeSort(Rec *a, int low, int high, Rec *tmp,
                      int *cmp, int *mv, int stable, int verbose)
{
    int mid;
    if (low >= high) return;            /* ★ >= 而不是 ==，否则 low > high 时无限递归 */
    mid = low + (high - low) / 2;       /* ★ 防溢出 */
    mergeSort(a, low, mid, tmp, cmp, mv, stable, verbose);
    mergeSort(a, mid + 1, high, tmp, cmp, mv, stable, verbose);
    if (verbose) {
        printf("  合并 a[%d..%d]=", low, mid); printTagBody(a + low, mid - low + 1);
        printf("  与 a[%d..%d]=", mid + 1, high); printTagBody(a + mid + 1, high - mid);
    }
    mergeRec(a, low, mid, high, tmp, cmp, mv, stable);
    if (verbose) { printf("\n     -> "); printTagBody(a + low, high - low + 1); printf("\n"); }
}

/* 自底向上（迭代）版本：栈空间 O(1) */
static void mergeSortBu(Rec *a, int n, Rec *tmp, int *cmp, int *mv)
{
    int len, low, mid, high;
    for (len = 1; len < n; len *= 2) {
        for (low = 0; low < n; low += 2 * len) {
            mid = low + len - 1;
            if (mid >= n - 1) break;                    /* 后半段为空，跳过 */
            high = low + 2 * len - 1;
            if (high > n - 1) high = n - 1;
            mergeRec(a, low, mid, high, tmp, cmp, mv, 1);
        }
    }
}

static int mergeCount(Rec *a, int low, int mid, int high, Rec *tmp)
{
    int i = low, j = mid + 1, k = low, cnt = 0;
    while (i <= mid && j <= high) {
        if (a[i].key <= a[j].key) tmp[k++] = a[i++];
        else { tmp[k++] = a[j++]; cnt += mid - i + 1; } /* ★ 左半段剩下的全都比 a[j] 大 */
    }
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= high) tmp[k++] = a[j++];
    for (k = low; k <= high; k++) a[k] = tmp[k];
    return cnt;
}

static int mergeCountInv(Rec *a, int low, int high, Rec *tmp)
{
    int mid, c = 0;
    if (low >= high) return 0;
    mid = low + (high - low) / 2;
    c += mergeCountInv(a, low, mid, tmp);
    c += mergeCountInv(a, mid + 1, high, tmp);
    c += mergeCount(a, low, mid, high, tmp);
    return c;
}

/* 对照组：端点枢轴快排，只用来看比较次数怎么随数据变化 */
static int partition(Rec *a, int low, int high, int *cmp)
{
    Rec pv = a[low];
    while (low < high) {
        while (low < high) { (*cmp)++; if (a[high].key >= pv.key) high--; else break; }
        a[low] = a[high];
        while (low < high) { (*cmp)++; if (a[low].key <= pv.key) low++; else break; }
        a[high] = a[low];
    }
    a[low] = pv;
    return low;
}

static void quickSort(Rec *a, int low, int high, int *cmp)
{
    int p;
    if (low >= high) return;
    p = partition(a, low, high, cmp);
    quickSort(a, low, p - 1, cmp);
    quickSort(a, p + 1, high, cmp);
}

