#include <stdio.h>
#include <stdlib.h>

#define MAXN 1024
#define MAXR 1024

typedef struct { int key; int tag; } Rec;

static int nxt[MAXN];           /* 静态链表：nxt[i] 是元素 i 的后继下标，-1 表示链尾 */
static int bhead[MAXR], btail[MAXR];
static Rec buf[MAXN];

static void printBody(const Rec *a, int n)
{
    int i;
    for (i = 0; i < n; i++) { if (i > 0) printf(" "); printf("%d", a[i].key); }
}

static void printTagBody(const Rec *a, int n)
{
    int i;
    for (i = 0; i < n; i++) {
        if (i > 0) printf(" ");
        if (a[i].tag == 1) printf("%d(a)", a[i].key);
        else if (a[i].tag == 2) printf("%d(b)", a[i].key);
        else printf("%d", a[i].key);
    }
}

static void printOneTag(const Rec *a, int idx)
{
    if (a[idx].tag == 1) printf("%d(a)", a[idx].key);
    else if (a[idx].tag == 2) printf("%d(b)", a[idx].key);
    else printf("%d", a[idx].key);
}

static int sortedRec(const Rec *a, int n)
{
    int i;
    for (i = 1; i < n; i++) if (a[i - 1].key > a[i].key) return 0;
    return 1;
}

static unsigned long long rngState = 20260101ULL;
static int nextRand(int bound)
{
    rngState = rngState * 6364136223846793005ULL + 1442695040888963407ULL;
    return (int)((rngState >> 33) % (unsigned)bound);
}

/* LSD 链式基数排序。
   d = 趟数（位数），r = 桶数（每位的取值个数），tailInsert = 1 尾插（正确）/ 0 头插（错误写法）。
   *alloc 统计分配次数、*collect 统计收集次数、*clear 统计清空桶的次数 —— 三者相加就是 d·(2n+r)。
   ★ 全程不做任何关键字比较，所以没有 cmp 这个出参。 */
static void radixSort(Rec *a, int n, int d, int r, int tailInsert, int verbose,
                      int *alloc, int *collect, int *clear)
{
    int k, i, b, p, cnt, div, t;
    *alloc = 0; *collect = 0; *clear = 0;
    for (k = 0; k < d; k++) {
        div = 1;
        for (t = 0; t < k; t++) div *= r;              /* ★ 整数累乘，不用 pow */
        for (b = 0; b < r; b++) { bhead[b] = -1; btail[b] = -1; (*clear)++; }

        for (i = 0; i < n; i++) {                      /* ① 分配 */
            b = (a[i].key / div) % r;
            nxt[i] = -1;
            (*alloc)++;
            if (bhead[b] < 0) { bhead[b] = i; btail[b] = i; }
            else if (tailInsert) { nxt[btail[b]] = i; btail[b] = i; }
            else { nxt[i] = bhead[b]; bhead[b] = i; }   /* ★ 头插（错误写法） */
        }

        if (verbose) {
            printf("    第%d趟（按第%d位，div=%d）桶内容：\n", k + 1, k + 1, div);
            for (b = 0; b < r; b++) {
                if (bhead[b] < 0) continue;
                printf("      桶[%d]:", b);
                for (p = bhead[b]; p >= 0; p = nxt[p]) { printf(" "); printOneTag(a, p); }
                printf("\n");
            }
        }

        cnt = 0;                                       /* ② 收集 */
        for (b = 0; b < r; b++)
            for (p = bhead[b]; p >= 0; p = nxt[p]) { buf[cnt++] = a[p]; (*collect)++; }
        for (i = 0; i < n; i++) a[i] = buf[i];         /* 一次整体拷贝 */

        if (verbose) { printf("    收集后："); printTagBody(a, n); printf("\n"); }
    }
}

/* 对照组：端点枢轴快排（会数比较次数） */
static int partition(Rec *a, int low, int high, int *cmp)
{
    Rec pv = a[low];
    while (low < high) {
        while (low < high) { (*cmp)++; if (a[high].key >= pv.key) high--; else break; }
        a[low] = a[high];
        while (low < high) { (*cmp)++; if (a[low].key <= pv.key) low++; else break; }
        a[high] = a[low];
    }
    a[low] = pv;
    return low;
}

static void quickSort(Rec *a, int low, int high, int *cmp)
{
    int p;
    if (low >= high) return;
    p = partition(a, low, high, cmp);
    quickSort(a, low, p - 1, cmp);
    quickSort(a, p + 1, high, cmp);
}

static void makeRand(Rec *a, int n, int bound)
{
    int i;
    for (i = 0; i < n; i++) { a[i].key = nextRand(bound); a[i].tag = 0; }
}

