#include <stdio.h>
#include <string.h>

#define MAXN 256
#define MAXR 16

typedef struct { int key; int tag; } Rec;

/* 确定性伪随机：固定种子，输出可复现 */
static unsigned long long rngState = 20260101ULL;
static int nextRand(int bound)
{
    rngState = rngState * 6364136223846793005ULL + 1442695040888963407ULL;
    return (int)((rngState >> 33) % (unsigned)bound);
}

static void swapRec(Rec *x, Rec *y) { Rec t = *x; *x = *y; *y = t; }

/* ⌈log2 x⌉，整数递推，不用 math.h（避免 libm 依赖与浮点舍入） */
static int lgCeil(int x)
{
    int c = 0, t = 1;
    while (t < x) { t *= 2; c++; }
    return c;
}

/* 以下所有算法统一用 a[1..n] 布局，a[0] 留作哨兵；
   比较 = 一次关键字比较，移动 = 一次赋值（一次交换算 3 次赋值） */

static int sortedRec(const Rec *a, int n)
{
    int i;
    for (i = 2; i <= n; i++) if (a[i].key < a[i - 1].key) return 0;
    return 1;
}

/* tag==1 的记录是否仍在 tag==2 之前；找不到任一个返回 -1 */
static int stableOK(const Rec *a, int n)
{
    int i, p1 = -1, p2 = -1;
    for (i = 1; i <= n; i++) { if (a[i].tag == 1) p1 = i; if (a[i].tag == 2) p2 = i; }
    if (p1 < 0 || p2 < 0) return -1;
    return p1 < p2;
}

static void printBody(const Rec *a, int n)
{
    int i;
    for (i = 1; i <= n; i++) {
        if (i > 1) printf(" ");
        if (a[i].tag == 1) printf("%d(a)", a[i].key);
        else if (a[i].tag == 2) printf("%d(b)", a[i].key);
        else printf("%d", a[i].key);
    }
}

/* ---- 1 直接插入（哨兵） ---- */
static void insertSentinel(Rec *a, int n, int *cmp, int *mv)
{
    int i, j;
    *cmp = 0; *mv = 0;
    for (i = 2; i <= n; i++) {
        a[0] = a[i]; (*mv)++;
        for (j = i - 1; a[0].key < a[j].key; j--) { a[j + 1] = a[j]; (*mv)++; (*cmp)++; }
        (*cmp)++;
        a[j + 1] = a[0]; (*mv)++;
    }
}

/* ---- 2 折半插入（哨兵） ---- */
static void insertBinary(Rec *a, int n, int *cmp, int *mv)
{
    int i, j, low, high, mid;
    *cmp = 0; *mv = 0;
    for (i = 2; i <= n; i++) {
        a[0] = a[i]; (*mv)++;
        low = 1; high = i - 1;
        while (low <= high) {
            mid = low + (high - low) / 2;
            (*cmp)++;
            if (a[0].key >= a[mid].key) low = mid + 1;   /* >= 相等往右走，保证稳定 */
            else high = mid - 1;
        }
        for (j = i - 1; j >= low; j--) { a[j + 1] = a[j]; (*mv)++; }
        a[low] = a[0]; (*mv)++;
    }
}

/* ---- 3 希尔（Shell 原始增量 n/2, n/4, ... , 1） ---- */
static void shellSort(Rec *a, int n, int *cmp, int *mv)
{
    int d, i, j;
    *cmp = 0; *mv = 0;
    for (d = n / 2; d >= 1; d /= 2) {
        for (i = d + 1; i <= n; i++) {
            a[0] = a[i]; (*mv)++;
            for (j = i - d; j >= 1; j -= d) {
                (*cmp)++;
                if (a[0].key < a[j].key) { a[j + d] = a[j]; (*mv)++; }
                else break;
            }
            a[j + d] = a[0]; (*mv)++;
        }
    }
}

/* ---- 4 冒泡（交换标志） ---- */
static void bubbleFlag(Rec *a, int n, int *cmp, int *mv)
{
    int i, j, swapped;
    *cmp = 0; *mv = 0;
    for (i = n; i >= 2; i--) {
        swapped = 0;
        for (j = 1; j < i; j++) {
            (*cmp)++;
            if (a[j].key > a[j + 1].key) { swapRec(&a[j], &a[j + 1]); (*mv) += 3; swapped = 1; }
        }
        if (!swapped) break;
    }
}

/* ---- 5 快速（端点枢轴、填坑法） ---- */
static int partition(Rec *a, int low, int high, int *cmp, int *mv)
{
    Rec pv = a[low];
    (*mv)++;
    while (low < high) {
        while (low < high) { (*cmp)++; if (a[high].key >= pv.key) high--; else break; }
        if (low < high) { a[low] = a[high]; (*mv)++; low++; }
        while (low < high) { (*cmp)++; if (a[low].key <= pv.key) low++; else break; }
        if (low < high) { a[high] = a[low]; (*mv)++; high--; }
    }
    a[low] = pv; (*mv)++;
    return low;
}

static void quickSort(Rec *a, int low, int high, int *cmp, int *mv)
{
    int p;
    if (low >= high) return;
    p = partition(a, low, high, cmp, mv);
    quickSort(a, low, p - 1, cmp, mv);
    quickSort(a, p + 1, high, cmp, mv);
}

/* ---- 6 简单选择 ---- */
static void selectSort(Rec *a, int n, int *cmp, int *mv)
{
    int i, j, m;
    *cmp = 0; *mv = 0;
    for (i = 1; i < n; i++) {
        m = i;
        for (j = i + 1; j <= n; j++) { (*cmp)++; if (a[j].key < a[m].key) m = j; }
        if (m != i) { swapRec(&a[i], &a[m]); (*mv) += 3; }
    }
}

/* ---- 7 堆排序（1-based 大根堆，siftDown 用暂存法） ---- */
static void siftDown(Rec *a, int i, int n, int *cmp, int *mv)
{
    int c;
    Rec t = a[i];
    (*mv)++;
    for (c = 2 * i; c <= n; c *= 2) {
        if (c < n) { (*cmp)++; if (a[c].key < a[c + 1].key) c++; }
        (*cmp)++;
        if (t.key >= a[c].key) break;
        a[i] = a[c]; (*mv)++;
        i = c;
    }
    a[i] = t; (*mv)++;
}

static void heapSort(Rec *a, int n, int *cmp, int *mv)
{
    int i;
    *cmp = 0; *mv = 0;
    for (i = n / 2; i >= 1; i--) siftDown(a, i, n, cmp, mv);
    for (i = n; i >= 2; i--) {
        swapRec(&a[1], &a[i]); (*mv) += 3;
        siftDown(a, 1, i - 1, cmp, mv);
    }
}

/* ---- 8 归并（递归，<= 取左保证稳定） ---- */
static void mergePass(Rec *a, int low, int mid, int high, Rec *tmp, int *cmp, int *mv)
{
    int i = low, j = mid + 1, k = low;
    while (i <= mid && j <= high) {
        (*cmp)++;
        if (a[i].key <= a[j].key) tmp[k++] = a[i++];
        else tmp[k++] = a[j++];
        (*mv)++;
    }
    while (i <= mid) { tmp[k++] = a[i++]; (*mv)++; }
    while (j <= high) { tmp[k++] = a[j++]; (*mv)++; }
    for (i = low; i <= high; i++) { a[i] = tmp[i]; (*mv)++; }
}

static void mergeSortR(Rec *a, int low, int high, Rec *tmp, int *cmp, int *mv)
{
    int mid;
    if (low >= high) return;
    mid = low + (high - low) / 2;
    mergeSortR(a, low, mid, tmp, cmp, mv);
    mergeSortR(a, mid + 1, high, tmp, cmp, mv);
    mergePass(a, low, mid, high, tmp, cmp, mv);
}

/* ---- 9 基数（LSD、静态链表、尾插保证稳定） ---- */
static int rnxt[MAXN + 1];
static int rbhead[MAXR], rbtail[MAXR];
static Rec rbuf[MAXN + 1];

static void radixSort(Rec *a, int n, int d, int r, int *cmp, int *mv)
{
    int k, t, div, i, b, p, cnt;
    *cmp = 0; *mv = 0;                    /* ★ 关键字比较次数恒为 0 */
    for (k = 0; k < d; k++) {
        div = 1;
        for (t = 0; t < k; t++) div *= r; /* 整数累乘，不用 pow */
        for (b = 0; b < r; b++) rbhead[b] = -1;
        for (i = 1; i <= n; i++) {
            b = (a[i].key / div) % r;
            rnxt[i] = -1;
            if (rbhead[b] < 0) { rbhead[b] = i; rbtail[b] = i; }
            else { rnxt[rbtail[b]] = i; rbtail[b] = i; }   /* 尾插：稳定性的全部来源 */
        }
        cnt = 0;
        for (b = 0; b < r; b++)
            for (p = rbhead[b]; p >= 0; p = rnxt[p]) { rbuf[++cnt] = a[p]; (*mv)++; }
        for (i = 1; i <= n; i++) { a[i] = rbuf[i]; (*mv)++; }
    }
}

/* 统一入口：which = 0..8 对应 names[] 里的九种算法 */
static void runOne(int which, Rec *a, int n, Rec *tmp, int *cmp, int *mv)
{
    switch (which) {
    case 0: insertSentinel(a, n, cmp, mv); break;
    case 1: insertBinary(a, n, cmp, mv); break;
    case 2: shellSort(a, n, cmp, mv); break;
    case 3: bubbleFlag(a, n, cmp, mv); break;
    case 4: *cmp = 0; *mv = 0; quickSort(a, 1, n, cmp, mv); break;
    case 5: selectSort(a, n, cmp, mv); break;
    case 6: heapSort(a, n, cmp, mv); break;
    case 7: *cmp = 0; *mv = 0; mergeSortR(a, 1, n, tmp, cmp, mv); break;
    default: radixSort(a, n, 2, 10, cmp, mv); break;
    }
}

