    rngState = 20260101ULL;
    for (k = 1; k <= nSmall; k++) keys[3][k] = nextRand(100);

    printf("== ① 九种排序 × 四组数据（n=%d，a[1..n]，a[0] 留作哨兵）==\n", nSmall);
    printf("   四组数据依次是：%s / %s / %s / %s\n", dnames[0], dnames[1], dnames[2], dnames[3]);
    printf("   每行三个数组依次是「比较次数 / 移动次数（赋值次数）/ 是否升序」\n");
    for (s = 0; s < 9; s++) {
        for (d = 0; d < 4; d++) {
            work[0].key = 0; work[0].tag = 0;
            for (k = 1; k <= nSmall; k++) { work[k].key = keys[d][k]; work[k].tag = 0; }
            runOne(s, work, nSmall, tmp, &c, &m);
            cmp16[s][d] = c; mv16[s][d] = m; ok16[s][d] = sortedRec(work, nSmall);
        }
        printf("  %s：\n", names[s]);
        printf("    比较 =");
        for (d = 0; d < 4; d++) printf(" %d", cmp16[s][d]);
        printf("   移动 =");
        for (d = 0; d < 4; d++) printf(" %d", mv16[s][d]);
        printf("   升序 =");
        for (d = 0; d < 4; d++) printf("%d", ok16[s][d]);
        printf("\n");
    }

    printf("\n== ② 同一批伪随机数据放大到 n=%d：O(n^2) 组与 O(n log n) 组的差距 ==\n", nBig);
    printf("   每行：比较 / 移动 / 升序\n");
    for (s = 0; s < 9; s++) {
        rngState = 20260101ULL;                    /* 与 ① 的第 4 组同种子，前 16 个值完全相同 */
        work[0].key = 0; work[0].tag = 0;
        for (k = 1; k <= nBig; k++) { work[k].key = nextRand(100); work[k].tag = 0; }
        runOne(s, work, nBig, tmp, &c, &m);
        cmp200[s] = c; mv200[s] = m; ok200[s] = sortedRec(work, nBig);
        printf("  %s：比较=%d 移动=%d 升序=%d\n", names[s], c, m, ok200[s]);
    }
    {
        int sq[3] = { 0, 3, 5 };        /* 比较次数真为 O(n^2) 的三种：直接插入/冒泡/简单选择 */
        double sqC = 0.0, sqM = 0.0, lSum = 0.0, scale = (double)nBig / nSmall;
        double thN2 = scale * scale;
        double thNlg = (double)nBig * lgCeil(nBig) / ((double)nSmall * lgCeil(nSmall));
        for (i = 0; i < 3; i++) {
            sqC += (double)cmp200[sq[i]] / cmp16[sq[i]][3];
            sqM += (double)mv200[sq[i]] / mv16[sq[i]][3];
        }
        for (i = 0; i < 3; i++) lSum += (double)cmp200[nlgn[i]] / cmp16[nlgn[i]][3];
        printf("  ★ n 从 %d 放大到 %d（×%.1f），实测放大倍数：\n", nSmall, nBig, scale);
        printf("    比较次数真为 O(n^2) 的三种（直接插入/冒泡/简单选择）：比较平均 ×%.1f、移动平均 ×%.1f，理论 ×%.1f\n",
               sqC / 3, sqM / 3, thN2);
        printf("    O(n log n) 的三种（快排/堆排/归并）：比较平均 ×%.1f，按 ⌈log2⌉ 估算的理论值 ×%.1f\n",
               lSum / 3, thNlg);
        printf("    基数排序不做比较，改看移动次数：×%.2f，而 2·d·n 的理论值是 ×%.1f（严格线性）\n",
               (double)mv200[8] / mv16[8][3], scale);
        printf("  ★ 折半插入是「比较与移动不同阶」的典型：比较 ×%.1f（接近 n log n），移动 ×%.1f（仍是 n^2）\n",
               (double)cmp200[1] / cmp16[1][3], (double)mv200[1] / mv16[1][3]);
        printf("    ⇒ 所以它的总时间仍是 O(n^2)：省下的 %d 次比较没有改变数量级\n", cmp200[0] - cmp200[1]);
        printf("  ★ 希尔单独看：比较 ×%.1f、移动 ×%.1f（既不属于 n^2 组也不属于 n log n 组，取决于增量序列）\n",
               (double)cmp200[2] / cmp16[2][3], (double)mv200[2] / mv16[2][3]);
    }

    printf("\n== ③ 稳定性实测：两组带 tag 的数据（tag 1 打成 (a)、tag 2 打成 (b)）==\n");
    for (k = 1; k <= n1; k++) { d1[k].key = s1k[k - 1]; d1[k].tag = s1t[k - 1]; }
    for (k = 1; k <= n2; k++) { d2[k].key = s2k[k - 1]; d2[k].tag = s2t[k - 1]; }
    printf("  S1（n=%d）：", n1); printBody(d1, n1); printf("\n");
    printf("  S2（n=%d）：", n2); printBody(d2, n2);
    printf("   ← 这是 ds-ch08-07 里希尔排序的最小反例\n");
    for (s = 0; s < 9; s++) {
        int r1, r2, o1, o2;
        memcpy(work, d1, sizeof(Rec) * (MAXN + 1));
        work[0].key = 0; work[0].tag = 0;
        runOne(s, work, n1, tmp, &c, &m);
        r1 = stableOK(work, n1); o1 = sortedRec(work, n1);
        memcpy(work, d2, sizeof(Rec) * (MAXN + 1));
        work[0].key = 0; work[0].tag = 0;
        runOne(s, work, n2, tmp, &c, &m);
        r2 = stableOK(work, n2); o2 = sortedRec(work, n2);
        st1[s] = r1; st2[s] = r2;
        if (r1 == 0 || r2 == 0) bad++;
        printf("  %s：S1 稳定？%d 升序？%d | S2 稳定？%d 升序？%d\n", names[s], r1, o1, r2, o2);
    }
    printf("  ★ 在 S1 或 S2 上出现不稳定的算法有 %d 个：", bad);
    for (s = 0; s < 9; s++) if (st1[s] == 0 || st2[s] == 0) printf(" %s", names[s]);
    printf("\n");
    printf("  ★ 一组不稳定就足以断定该算法不稳定；反过来两组都稳定**不能**证明它稳定\n");

    printf("\n== ④ 由上面的实测数据直接筛出的选型结论（没有一个数字是写死的）==\n");
    for (s = 0; s < 9; s++) {
        int sameC = 1, sameM = 1;
        for (d = 1; d < 4; d++) {
            if (cmp16[s][d] != cmp16[s][0]) sameC = 0;
            if (mv16[s][d] != mv16[s][0]) sameM = 0;
        }
        indepC[s] = sameC; indepM[s] = sameM;
    }
    printf("  ★ 稳定的算法：");
    for (s = 0; s < 9; s++) if (st1[s] == 1 && st2[s] == 1) printf(" %s", names[s]);
    printf("\n");
    printf("  ★ 不稳定的算法：");
    for (s = 0; s < 9; s++) if (st1[s] == 0 || st2[s] == 0) printf(" %s", names[s]);
    printf("\n");
    {
        int bestStC = -1, bestStT = -1, bestUnC = -1, bestUnT = -1, bestAll = 0;
        for (s = 0; s < 9; s++) {
            if (s == 8) continue;                 /* 基数比较次数恒为 0，不参与「只比比较」这项评比 */
            if (st1[s] == 1 && st2[s] == 1) {
                if (bestStC < 0 || cmp200[s] < cmp200[bestStC]) bestStC = s;
                if (bestStT < 0 || cmp200[s] + mv200[s] < cmp200[bestStT] + mv200[bestStT]) bestStT = s;
            } else {
                if (bestUnC < 0 || cmp200[s] < cmp200[bestUnC]) bestUnC = s;
                if (bestUnT < 0 || cmp200[s] + mv200[s] < cmp200[bestUnT] + mv200[bestUnT]) bestUnT = s;
            }
        }
        for (s = 1; s < 9; s++)
            if (cmp200[s] + mv200[s] < cmp200[bestAll] + mv200[bestAll]) bestAll = s;
        printf("  ★ 稳定组：n=%d 时「比较+移动」合计最少的是 %s（%d 次）；只比关键字比较次数最少的是 %s（%d 次）\n",
               nBig, names[bestStT], cmp200[bestStT] + mv200[bestStT], names[bestStC], cmp200[bestStC]);
        if (bestStT == bestStC) printf("    ⇒ 这一组两种口径给出同一个答案\n");
        else printf("    ⇒ 两者不同！%s 的比较次数虽少，但移动次数高达 %d，合计反而更贵 —— 只看比较次数会选错\n",
                    names[bestStC], mv200[bestStC]);
        printf("  ★ 不稳定组：合计最少的是 %s（%d 次）；只比比较次数最少的是 %s（%d 次）\n",
               names[bestUnT], cmp200[bestUnT] + mv200[bestUnT], names[bestUnC], cmp200[bestUnC]);
        if (bestUnT == bestUnC) printf("    ⇒ 这一组两种口径给出同一个答案\n");
        else printf("    ⇒ 两者不同：%s 的移动次数高达 %d\n", names[bestUnC], mv200[bestUnC]);
        printf("  ★ 九种里「比较+移动」合计最少的是：%s（%d 次，其中比较 %d 次）\n",
               names[bestAll], cmp200[bestAll] + mv200[bestAll], cmp200[bestAll]);
        if (bestAll == 8)
            printf("    它的比较次数恒为 0（基数排序不做关键字比较），代价全部体现在移动 %d = 2·d·n 上\n", mv200[8]);
        else
            printf("    而基数排序的合计是 %d（比较 %d 次 + 移动 %d 次）\n",
                   cmp200[8] + mv200[8], cmp200[8], mv200[8]);
    }
    printf("  ★ 比较次数与数据完全无关的算法：");
    for (s = 0; s < 9; s++) if (indepC[s]) printf(" %s", names[s]);
    printf("\n");
    printf("  ★ 移动次数与数据完全无关的算法：");
    for (s = 0; s < 9; s++) if (indepM[s]) printf(" %s", names[s]);
    printf("\n");
    {
        int allOk = 1;
        for (s = 0; s < 9; s++) {
            for (d = 0; d < 4; d++) if (!ok16[s][d]) allOk = 0;
            if (!ok200[s]) allOk = 0;
        }
        printf("  ★ 九种算法在四组 n=%d 数据与 n=%d 数据上是否全部升序：%d\n", nSmall, nBig, allOk);
    }
    return 0;
}
